"""The load pipeline."""

from data.ingest.reader import read_trades


def run_load(path: str) -> int:
    """Read the trades at path, the default file when path is empty, and return their count."""
    if not path:
        return run_load("trades.csv")
    rows = read_trades(path)
    return len(rows)
